// EDIT THESE: where the digest goes and how many competitors to check per run.
return [{ json: {
  email: 'pagecraftapi@gmail.com',     // digest and alerts go here
  maxCompetitors: 10,           // hard cap per run (cost about $0.06 per competitor at Apify Free-plan prices)
  newsCountry: 'GB',            // Google News edition: GB, US, IE, AU, DE...
  highPriorityScore: 5          // change score at or above this sends an immediate alert
} }];

const host = u => String(u || '').trim().toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/^www\d*\./, '').split(/[\/?#:]/)[0];
// One list of competitors from the "Competitors" tab: columns Website (required) and Name (optional, used for news).
const s = $('Your settings').first().json;
const seen = new Set(); const competitors = [];
for (const i of $('Read competitors').all()) {
  const domain = host(i.json.Website ?? i.json.website);
  if (!domain.includes('.') || seen.has(domain)) continue;
  seen.add(domain);
  competitors.push({ domain, name: String(i.json.Name ?? i.json.name ?? '').trim() || domain });
}
if (!competitors.length) throw new Error('No competitors found. Put their websites in a column called "Website" on the Competitors tab.');
const list = competitors.slice(0, s.maxCompetitors);
const since = new Date(Date.now() - 7 * 864e5).toISOString().slice(0, 10);
return [{ json: { competitors: list, domains: list.map(c => c.domain), queries: list.map(c => c.name), since, skipped: competitors.length - list.length } }];

const host = u => String(u || '').trim().toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/^www\d*\./, '').split(/[\/?#:]/)[0];
// Compare this week with last week's snapshot and score what changed. Failed sites stay in the report.
const all = n => { try { return $(n).all().map(i => i.json); } catch { return []; } };
const s = $('Your settings').first().json;
const { competitors, since } = $('Collect competitors').first().json;
const prev = {}; for (const r of all('Read last week')) { const k = host(r.Website); if (k) prev[k] = r; }
const prof = {}; for (const r of all('Company profile')) { const k = host(r.domain || r.input); if (k && !prof[k]) prof[k] = r; }
const news = {}; for (const r of all('News this week')) { if (!r.title) continue; (news[String(r.query || '').toLowerCase()] ||= []).push(r); }
const pages = {}; for (const r of all('New pages')) { if (!r.url) continue; const k = host(r.input); (pages[k] ||= new Set()).add(r.url); }
const today = new Date().toISOString().slice(0, 10);
return competitors.map(({ domain, name }) => {
  const p = prof[domain] || {}; const last = prev[domain];
  const ok = p.domain && !p.error && (p.statusCode || 200) < 400;
  const tech = [...new Set([...(p.technologies || []).map(t => t && (t.name || t)), ...Object.values(p.technologiesByCategory || {}).flat()].filter(t => typeof t === 'string' && t))].sort();
  const lastTech = last ? String(last.Technologies || '').split(', ').filter(Boolean) : null;
  const added = lastTech && ok ? tech.filter(t => !lastTech.includes(t)) : [];
  const removed = lastTech && ok ? lastTech.filter(t => !tech.includes(t)) : [];
  const newPages = [...(pages[domain] || [])];
  const headlines = (news[name.toLowerCase()] || []).slice(0, 10);
  const wasUp = last && last.Status === 'ok';
  let score = 2 * Math.min(added.length + removed.length, 4);
  score += newPages.length >= 20 ? 2 : newPages.length >= 5 ? 1 : 0;
  score += headlines.length >= 5 ? 2 : headlines.length >= 1 ? 1 : 0;
  if (!ok && wasUp) score += 3;
  return { json: {
    Website: domain, Name: name, Checked: today,
    Status: ok ? 'ok' : String(p.error || ('HTTP ' + (p.statusCode || 'no response'))).slice(0, 120),
    Company: p.companyName || '', Technologies: tech.join(', '),
    'Tech added': lastTech ? added.join(', ') : 'first run (baseline)', 'Tech removed': removed.join(', '),
    'New pages': newPages.length, 'Sample new pages': newPages.slice(0, 5).join(' | '),
    'News count': headlines.length, 'Top headlines': headlines.slice(0, 3).map(h => h.title + ' (' + (h.source || '') + ')').join(' | '),
    'Change score': score, Priority: score >= s.highPriorityScore ? 'High' : score >= 2 ? 'Medium' : 'Low', Since: since
  } };
});

// Build the weekly digest (all competitors) and the alert (high priority only) as HTML emails.
const rows = $input.all().map(i => i.json).sort((a, b) => b['Change score'] - a['Change score']);
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const card = r => `<h3 style="margin:16px 0 4px">${esc(r.Name)} <span style="color:#666;font-weight:normal">(${esc(r.Website)})</span> &middot; ${esc(r.Priority)} (${r['Change score']})</h3>
<ul style="margin:0">${r.Status !== 'ok' ? `<li><b>Site check failed:</b> ${esc(r.Status)}</li>` : ''}
<li><b>Tech added:</b> ${esc(r['Tech added'] || 'none')} &middot; <b>removed:</b> ${esc(r['Tech removed'] || 'none')}</li>
<li><b>New or changed pages (7 days):</b> ${r['New pages']}${r['Sample new pages'] ? ' e.g. ' + esc(r['Sample new pages']) : ''}</li>
<li><b>News (7 days):</b> ${r['News count']}${r['Top headlines'] ? ': ' + esc(r['Top headlines']) : ''}</li></ul>`;
const high = rows.filter(r => r.Priority === 'High');
const skipped = $('Collect competitors').first().json.skipped;
const foot = `<p style="color:#666;font-size:12px">${rows.length} competitors checked${skipped ? `, ${skipped} skipped (raise maxCompetitors)` : ''}. Data from Pagecraft tools on Apify: Company Enrichment by Domain, Google News Scraper, Wayback Machine Snapshots.</p>`;
return [{ json: {
  alertCount: high.length,
  alertSubject: `Competitor alert: ${high.map(r => r.Name).join(', ')}`,
  alertHtml: `<p>Big changes this week:</p>${high.map(card).join('')}${foot}`,
  digestSubject: `Weekly competitor watch: ${high.length} high, ${rows.filter(r => r.Priority === 'Medium').length} medium`,
  digestHtml: `<p>Changes since last week, biggest first.</p>${rows.map(card).join('')}${foot}`
} }];
